        /// <summary>The Resources path of an app file ("sfx/tap.wav" -> "Audio/sfx/tap").</summary>
        public static string ResourcePath(string file)
        {
            int dot = file.LastIndexOf('.');
            return "Audio/" + (dot > 0 ? file.Substring(0, dot) : file);
        }
